# enumerate core arrays normalized and compaction transforms
cores={}
for name,gi,go,ib,ob in [('L',demo['input'],demo['output'],(0,13,2,12),(0,13,2,12)),('R',demo['input'],demo['output'],(0,13,14,24),(0,13,14,24)),('A',in2,out2,(2,24,2,24),(2,24,2,24)),('B',in2,out2,(2,24,2,24),(2,24,2,24))]:
 def core(g,b):
  C=coords(g,{8,9},b); arr=np.zeros((len(g),len(g[0])),int)
  for r,c in C:arr[r,c]=1
  lab,n=label(arr);sizes=[np.sum(lab==i) for i in range(1,n+1)]; k=1+np.argmax(sizes)
  C={(r,c) for r,c in C if lab[r,c]==k}; mr=min(r for r,c in C);mc=min(c for r,c in C)
  return {(r-mr,c-mc) for r,c in C}
 cores[name]=(core(gi,ib),core(go,ob))
def arr(S):
 h=max(r for r,c in S)+1;w=max(c for r,c in S)+1;a=np.zeros((h,w),int)
 for r,c in S:a[r,c]=1
 return a
def sett(a):return {(r,c) for r,c in zip(*np.where(a))}
def compact(a,d):
 # 0 up 1 down 2 left 3 right, stable compact nonzero cells
 if d<2:
  a=a if d==0 else a[::-1]
  for c in range(a.shape[1]):
   vals=a[:,c][a[:,c]>0];a[:,c]=0;a[:len(vals),c]=vals
  return a if d==0 else a[::-1]
 a=a if d==2 else a[:,::-1]
 for r in range(a.shape[0]):
  vals=a[r][a[r]>0];a[r]=0;a[r,:len(vals)]=vals
 return a if d==2 else a[:,::-1]
for name,(I,O) in cores.items():
 found=[]
 for k in range(4):
  for refl in [0,1]:
   a=arr(I);a=np.fliplr(a) if refl else a;a=np.rot90(a,k)
   for d in range(4):
    b=compact(a.copy(),d)
    if sett(b)==O:found.append((k,refl,d))
 print(name,found)

import itertools
for name,(I,O) in cores.items():
 best=[]
 for a,b,c,d in itertools.product(range(-2,3),repeat=4):
  if abs(a*d-b*c)!=1:continue
  T={(a*r+b*c,c*r+d*c) for r,c in I}
  # error best translation
  err=99
  for ro,co in O:
   for ri,ci in T:
    dr,dc=ro-ri,co-ci;S={(r+dr,c+dc) for r,c in T};err=min(err,len(S^O))
  if err<=2:best.append((err,(a,b,c,d)))
 print(name,sorted(best)[:10])
